asus.org.br)", "modelo": "SEDE25-PROVA", "lido_em": "2026-10-02", "arquivos": ["https://agenciasus.org.br/shared-files/17857/?Edital%20N%C2%B0%2059%20%E2%80%93%20Unidade%20de%20Transformac%CC%A7a%CC%83o%20Digital%20em%20Sau%CC%81de%20%E2%80%93%20UDIGIS.pdf"], "pontuacao": {"documental_max": 100, "entrevista_max": null, "final_max": null, "por_nivel": {"superior": {"FORMACAO": 8, "CURSOS": 32, "EXPERIENCIA": 60}, "medio": {"FORMACAO": 8, "CURSOS": 32, "EXPERIENCIA": 60}}, "detalhe": "Assistente: mestrado 8, especialização/residência 4; Agente: curso técnico 8; cursos ≥20h 8 cada até 32; experiência 10 por 6 meses até 60"}, "em_aberto": ["Etapa NÃO modelada: a nota final é a da Avaliação de Conhecimentos/teste de habilidades (prova objetiva e/ou discursiva; mínimo de 50% da pontuação). A regra gerada classifica só pela análise curricular (lista preliminar e base da convocação para a prova); o resultado final depende da prova. Alternativa provisória do gestor: lançar a nota da prova como 'nota da entrevista' e usar composição [ENTREVISTA 1] com mínimo = 50% da pontuação da prova.", "Convocação para a prova (não modelada): até 10× o número de vagas (inclui cadastro reserva quando o edital diz).", "Para compor o cadastro reserva o candidato precisa de ≥ 50 pontos na prova (não modelado).", "Empate depois de todos os critérios: o edital não define → 'mesma posição' (densa) provisória; gestor decide: sorteio registrado, ordem de inscrição, mesma posição ou decisão manual.", "Reserva de 30% é CONJUNTA para pretos, pardos e quilombolas (uma só modalidade, código PP aqui). O sistema lê a modalidade do candidato por código (quilombola→PQ): conferir se os cotistas quilombolas entram na modalidade PP ou criar uma modalidade conjunta.", "Base de cálculo da reserva: o edital aplica o percentual sobre as vagas do edital e a tabela 1.4 já distribui as vagas reservadas por cargo — conferir as vagas por modalidade no cadastro das vagas.", "Acúmulo PcD + PPQ: o edital não diz → TODAS (provisório).", "Data de corte: o edital remete ao cronograma (anexo não baixado); a regra usa o fim das inscrições do cronograma do MONITORA."]}}$r$::jsonb)
    ) v(edital_id, numero, area, modelo, configuracao)
  loop
    perform private."FC_VALIDAR_REGRA_CLASSIFICACAO"(r.configuracao);
    select e.id, e.edital, e."CO_AREA" into v_edital
      from public."TB_MONITORAMENTO_INDIGENA" e
     where e.id = r.edital_id;
    if v_edital.id is null
       or private."FC_NUMERO_EDITAL"(v_edital.edital) is distinct from private."FC_NUMERO_EDITAL"(r.numero)
       or v_edital."CO_AREA" is distinct from r.area then
      v_sem_edital := v_sem_edital + 1;
      raise notice 'Edital % (% / %) não encontrado com esse número e área; regra não criada.', r.numero, r.area, r.edital_id;
      continue;
    end if;
    if exists (select 1 from public."TB_REGRA_CLASSIFICACAO" x where x."CO_MONITORAMENTO" = r.edital_id) then
      v_ja_tinham := v_ja_tinham + 1;
      raise notice 'Edital % (%): já tem regra de classificação; nada muda.', r.numero, r.area;
      continue;
    end if;
    insert into public."TB_REGRA_CLASSIFICACAO" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE")
    values (r.edital_id, 1)
    returning "CO_REGRA_CLASSIFICACAO" into v_regra;
    insert into public."TH_REGRA_CLASSIFICACAO"
      ("CO_REGRA_CLASSIFICACAO", "NU_VERSAO", "DS_CONFIGURACAO", "TP_EMPATE_FINAL", "DS_MOTIVO")
    values (v_regra, 1, r.configuracao, r.configuracao #>> '{empate_final,metodo}',
            'Regra lida do edital (PDF oficial) — conferir');
    insert into public."RL_REGRA_CRITERIO_DESEMPATE"
      ("CO_REGRA_CLASSIFICACAO", "NU_VERSAO", "NU_ORDEM", "CO_CRITERIO", "TP_DIRECAO")
    select v_regra, 1, d.ordem, upper(d.valor ->> 'criterio'), d.valor ->> 'direcao'
      from jsonb_array_elements(r.configuracao -> 'desempate') with ordinality d(valor, ordem);
    v_criadas := v_criadas + 1;
  end loop;
  raise notice 'Regras criadas: %; editais que já tinham regra: %; não encontrados: %.', v_criadas, v_ja_tinham, v_sem_edital;
end;
$seed$;

select pg_temp.aplicar_regras_dos_editais();

commit;
